import networkx as nx

def k_colorable(G,k):
    colors={}
    def search():
        if len(colors)==len(G): return True
        v=max((v for v in G if v not in colors), key=lambda v:(len({colors[w] for w in G[v] if w in colors}),G.degree(v)))
        bad={colors[w] for w in G[v] if w in colors}
        for c in range(min(k,1+max(colors.values(),default=-1)+1)):
            if c not in bad:
                colors[v]=c
                if search(): return True
                del colors[v]
        return False
    return search()

for r in range(2,6):
    # Bowtie, joined to r-2 independent pairs.
    B=nx.Graph([(0,1),(1,2),(2,0),(0,3),(3,4),(4,0)])
    H=B.copy()
    parts=[{0,1,2,3,4}]+[{5+2*i,6+2*i} for i in range(r-2)]
    for P in parts:
        H.add_nodes_from(P)
    for i,P in enumerate(parts):
        for Q in parts[i+1:]:
            H.add_edges_from((u,v) for u in P for v in Q)
    critical=[]
    for u,v in list(H.edges()):
        J=H.copy(); J.remove_edge(u,v)
        if k_colorable(J,r): critical.append((u,v))
    print('r =',r,': chi =',r+1,'verified =',not k_colorable(H,r) and k_colorable(H,r+1),'; color-critical edges =',critical)
    # Deleting independent classes leaves either 2K2 or P3.
    matching_remainder=H.subgraph({1,2,3,4})
